import{_ as e,o as a,c as n,a2 as o}from"./chunks/framework.O93z6AWZ.js";const c="/hmyt-book/labs_chuyen_de/ch02_suy_tim_risk_dxai/01_eda_overview.png",r="/hmyt-book/labs_chuyen_de/ch02_suy_tim_risk_dxai/04_shap_summary.png",_=JSON.parse('{"title":"Case Study: Suy tim (Chương 2)","description":"","frontmatter":{"title":"Case Study: Suy tim (Chương 2)"},"headers":[],"relativePath":"labs_chuyen_de/ch02_suy_tim_risk_dxai.md","filePath":"labs_chuyen_de/ch02_suy_tim_risk_dxai.md"}'),s={name:"labs_chuyen_de/ch02_suy_tim_risk_dxai.md"};function i(h,t,l,g,d,b){return a(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="case-study-chuong-2-du-bao-tu-vong-suy-tim-heart-failure-clinical-records" tabindex="-1">Case Study Chương 2: Dự báo tử vong Suy tim (Heart Failure Clinical Records) <a class="header-anchor" href="#case-study-chuong-2-du-bao-tu-vong-suy-tim-heart-failure-clinical-records" aria-label="Permalink to &quot;Case Study Chương 2: Dự báo tử vong Suy tim (Heart Failure Clinical Records)&quot;">​</a></h1><p>Áp dụng lý thuyết <a href="/hmyt-book/ch02">Chương 2 — Khám phá &amp; Tiền xử lý dữ liệu y tế</a> vào 1 bài toán lâm sàng thật, chạy được ngay: dự báo tử vong ở bệnh nhân suy tim từ 12 đặc trưng lâm sàng dạng bảng. Bài toán dùng cùng dữ liệu với <a href="/hmyt-book/du_an/suy_tim_risk_dxai">Đề tài 3.4 — Suy tim cấp tốc</a>.</p><div class="danger custom-block"><p class="custom-block-title">⚠️ Không dùng để nộp Đề tài 3.4</p><p>Đề tài 3.4 giữ mã nguồn giải pháp <strong>Private</strong> theo Zero-Code Policy để sinh viên tự code (xem <a href="/hmyt-book/du_an/suy_tim_risk_dxai_lab">Lab Manual Đề tài 3.4</a>). 4 notebook dưới đây là <strong>lời giải minh họa công khai của giáo trình</strong> — nếu bạn đang làm Đề tài 3.4 để lấy điểm, đây KHÔNG phải bài nộp hợp lệ.</p></div><div class="tip custom-block"><p class="custom-block-title">Dữ liệu thật, không mô phỏng</p><p>Khác với 8 Code Lab ở <a href="/hmyt-book/labs">Kho Code Labs</a> (dùng dữ liệu giả lập theo <code>np.random.seed</code>), case study này chạy trên <a href="https://archive.ics.uci.edu/dataset/519/heart+failure+clinical+records" target="_blank" rel="noreferrer">Heart Failure Clinical Records</a> thật (UCI #519, CC BY 4.0, 299 bệnh nhân) — mọi số liệu dưới đây lấy trực tiếp từ 1 lần thực thi notebook thật, không chỉnh sửa để khớp y văn.</p></div><h2 id="chay-truc-tuyen-—-tung-buoc-hoac-toan-bo" tabindex="-1">Chạy trực tuyến — từng bước hoặc toàn bộ <a class="header-anchor" href="#chay-truc-tuyen-—-tung-buoc-hoac-toan-bo" aria-label="Permalink to &quot;Chạy trực tuyến — từng bước hoặc toàn bộ&quot;">​</a></h2><p>Mỗi notebook bên dưới <strong>tự tải dữ liệu và tự cài thư viện còn thiếu</strong> (<code>imbalanced-learn</code>, <code>shap</code>) khi mở qua Colab/Kaggle — bấm 1 nút, chọn <strong>Runtime → Run all</strong> là chạy được ngay, không cần cài đặt môi trường cục bộ. Muốn làm <strong>từng bước</strong>: mở lần lượt từng notebook. Muốn chạy <strong>toàn bộ bài thực hành</strong>: mở và &quot;Run all&quot; tuần tự <code>1_eda</code> → <code>2_baseline</code> → <code>3_improvement</code> → <code>4_xai</code> (mỗi notebook tự nạp lại dữ liệu và tái lập đúng bước trước, không phụ thuộc trạng thái notebook trước đó).</p><table tabindex="0"><thead><tr><th>Notebook</th><th style="text-align:center;">Colab</th><th style="text-align:center;">Kaggle</th></tr></thead><tbody><tr><td><code>1_eda.ipynb</code></td><td style="text-align:center;"><a href="https://colab.research.google.com/github/fossbk-spec/hmyt-book/blob/gh-pages/labs_chuyen_de/ch02_suy_tim_risk_dxai/1_eda.ipynb" target="_blank" rel="noreferrer"><img src="https://colab.research.google.com/assets/colab-badge.svg" alt="Colab"></a></td><td style="text-align:center;"><a href="https://www.kaggle.com/kernels/welcome?src=https://raw.githubusercontent.com/fossbk-spec/hmyt-book/gh-pages/labs_chuyen_de/ch02_suy_tim_risk_dxai/1_eda.ipynb" target="_blank" rel="noreferrer"><img src="https://kaggle.com/static/images/open-in-kaggle.svg" alt="Kaggle"></a></td></tr><tr><td><code>2_baseline.ipynb</code></td><td style="text-align:center;"><a href="https://colab.research.google.com/github/fossbk-spec/hmyt-book/blob/gh-pages/labs_chuyen_de/ch02_suy_tim_risk_dxai/2_baseline.ipynb" target="_blank" rel="noreferrer"><img src="https://colab.research.google.com/assets/colab-badge.svg" alt="Colab"></a></td><td style="text-align:center;"><a href="https://www.kaggle.com/kernels/welcome?src=https://raw.githubusercontent.com/fossbk-spec/hmyt-book/gh-pages/labs_chuyen_de/ch02_suy_tim_risk_dxai/2_baseline.ipynb" target="_blank" rel="noreferrer"><img src="https://kaggle.com/static/images/open-in-kaggle.svg" alt="Kaggle"></a></td></tr><tr><td><code>3_improvement.ipynb</code></td><td style="text-align:center;"><a href="https://colab.research.google.com/github/fossbk-spec/hmyt-book/blob/gh-pages/labs_chuyen_de/ch02_suy_tim_risk_dxai/3_improvement.ipynb" target="_blank" rel="noreferrer"><img src="https://colab.research.google.com/assets/colab-badge.svg" alt="Colab"></a></td><td style="text-align:center;"><a href="https://www.kaggle.com/kernels/welcome?src=https://raw.githubusercontent.com/fossbk-spec/hmyt-book/gh-pages/labs_chuyen_de/ch02_suy_tim_risk_dxai/3_improvement.ipynb" target="_blank" rel="noreferrer"><img src="https://kaggle.com/static/images/open-in-kaggle.svg" alt="Kaggle"></a></td></tr><tr><td><code>4_xai.ipynb</code></td><td style="text-align:center;"><a href="https://colab.research.google.com/github/fossbk-spec/hmyt-book/blob/gh-pages/labs_chuyen_de/ch02_suy_tim_risk_dxai/4_xai.ipynb" target="_blank" rel="noreferrer"><img src="https://colab.research.google.com/assets/colab-badge.svg" alt="Colab"></a></td><td style="text-align:center;"><a href="https://www.kaggle.com/kernels/welcome?src=https://raw.githubusercontent.com/fossbk-spec/hmyt-book/gh-pages/labs_chuyen_de/ch02_suy_tim_risk_dxai/4_xai.ipynb" target="_blank" rel="noreferrer"><img src="https://kaggle.com/static/images/open-in-kaggle.svg" alt="Kaggle"></a></td></tr></tbody></table><blockquote><p>Link Colab trỏ tới bản mirror công khai trên <code>hmyt-book</code> (repo nguồn <code>HMYT</code> là Private nên Colab không đọc được trực tiếp) — nội dung giống hệt bản trong repo nguồn, chỉ đồng bộ một chiều tự động.</p></blockquote><h2 id="du-lieu-y-van-nen-tang" tabindex="-1">Dữ liệu &amp; Y văn nền tảng <a class="header-anchor" href="#du-lieu-y-van-nen-tang" aria-label="Permalink to &quot;Dữ liệu &amp; Y văn nền tảng&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Dataset</strong></td><td>Heart Failure Clinical Records (UCI #519) — 299 bệnh nhân, 13 đặc trưng, <strong>không khuyết thiếu</strong></td></tr><tr><td><strong>Nhãn</strong></td><td><code>DEATH_EVENT</code> nhị phân — 203 sống sót (67,9%) / 96 tử vong (32,1%)</td></tr><tr><td><strong>Y văn Bước 2</strong></td><td><code>chicco2020machine</code> — Random Forest, Accuracy 74,0%, MCC 0,384</td></tr><tr><td><strong>Y văn Bước 3</strong></td><td><code>ishaq2021improving</code> — Extra Trees + SMOTE, Accuracy 92,6%</td></tr><tr><td><strong>Y văn tổng quan</strong></td><td><code>mpanya2021predicting</code> — tổng quan hệ thống 30 nghiên cứu ML cho suy tim</td></tr></tbody></table><h2 id="buoc-1-—-kham-pha-chuan-bi-du-lieu" tabindex="-1">Bước 1 — Khám phá &amp; Chuẩn bị dữ liệu <a class="header-anchor" href="#buoc-1-—-kham-pha-chuan-bi-du-lieu" aria-label="Permalink to &quot;Bước 1 — Khám phá &amp; Chuẩn bị dữ liệu&quot;">​</a></h2><p>Áp dụng Mục 2.3 (EDA), 2.4 (nền tảng toán chuẩn hóa), 2.5 (Lý thuyết Rubin về dữ liệu thiếu — minh họa bổ sung vì dữ liệu gốc không khuyết thiếu), 2.6 (pipeline 4 bước chống rò rỉ), 2.7 (chuẩn dữ liệu y tế thực tế).</p><p><img src="'+c+'" alt="EDA tổng quan: phân bố nhãn và ma trận tương quan"></p><p><strong>Kết quả:</strong> không có giá trị khuyết thiếu trong dữ liệu gốc; mất cân bằng nhãn vừa phải (32,1% tử vong); Train/Test chia 239/60 theo <code>stratify=True</code>, <code>random_state=42</code>.</p><p>👉 <a href="/hmyt-book/labs_chuyen_de/ch02_suy_tim_risk_dxai/1_eda.ipynb">Tải <code>1_eda.ipynb</code></a>   <a href="https://colab.research.google.com/github/fossbk-spec/hmyt-book/blob/gh-pages/labs_chuyen_de/ch02_suy_tim_risk_dxai/1_eda.ipynb" target="_blank" rel="noreferrer"><img src="https://colab.research.google.com/assets/colab-badge.svg" alt="Colab"></a><a href="https://www.kaggle.com/kernels/welcome?src=https://raw.githubusercontent.com/fossbk-spec/hmyt-book/gh-pages/labs_chuyen_de/ch02_suy_tim_risk_dxai/1_eda.ipynb" target="_blank" rel="noreferrer"><img src="https://kaggle.com/static/images/open-in-kaggle.svg" alt="Kaggle"></a></p><h2 id="buoc-2-—-tai-lap-y-van-goc-baseline" tabindex="-1">Bước 2 — Tái lập Y văn gốc (Baseline) <a class="header-anchor" href="#buoc-2-—-tai-lap-y-van-goc-baseline" aria-label="Permalink to &quot;Bước 2 — Tái lập Y văn gốc (Baseline)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mô hình</th><th style="text-align:center;">Accuracy</th><th style="text-align:center;">MCC</th><th style="text-align:center;">F1</th></tr></thead><tbody><tr><td>Logistic Regression</td><td style="text-align:center;">0,8167</td><td style="text-align:center;">0,5563</td><td style="text-align:center;">0,6667</td></tr><tr><td>Random Forest</td><td style="text-align:center;">0,8167</td><td style="text-align:center;">0,5563</td><td style="text-align:center;">0,6667</td></tr><tr><td><strong><code>chicco2020machine</code> (y văn)</strong></td><td style="text-align:center;">0,7400</td><td style="text-align:center;">0,3840</td><td style="text-align:center;">—</td></tr></tbody></table><p>Random Forest baseline trong notebook này <strong>vượt</strong> mốc y văn (+7,67 điểm % Accuracy). Logistic Regression và Random Forest ra cùng 3 chỉ số dù dự đoán khác nhau ở 4/60 bệnh nhân — trùng ngẫu nhiên do cỡ mẫu Test nhỏ (n=60), không phải lỗi.</p><p>👉 <a href="/hmyt-book/labs_chuyen_de/ch02_suy_tim_risk_dxai/2_baseline.ipynb">Tải <code>2_baseline.ipynb</code></a>   <a href="https://colab.research.google.com/github/fossbk-spec/hmyt-book/blob/gh-pages/labs_chuyen_de/ch02_suy_tim_risk_dxai/2_baseline.ipynb" target="_blank" rel="noreferrer"><img src="https://colab.research.google.com/assets/colab-badge.svg" alt="Colab"></a><a href="https://www.kaggle.com/kernels/welcome?src=https://raw.githubusercontent.com/fossbk-spec/hmyt-book/gh-pages/labs_chuyen_de/ch02_suy_tim_risk_dxai/2_baseline.ipynb" target="_blank" rel="noreferrer"><img src="https://kaggle.com/static/images/open-in-kaggle.svg" alt="Kaggle"></a></p><h2 id="buoc-3-—-toi-uu-voi-smote" tabindex="-1">Bước 3 — Tối ưu với SMOTE <a class="header-anchor" href="#buoc-3-—-toi-uu-voi-smote" aria-label="Permalink to &quot;Bước 3 — Tối ưu với SMOTE&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Cấu hình</th><th style="text-align:center;">Accuracy</th><th style="text-align:center;">MCC</th><th style="text-align:center;">F1</th></tr></thead><tbody><tr><td>Extra Trees (không SMOTE)</td><td style="text-align:center;">0,7500</td><td style="text-align:center;">0,3685</td><td style="text-align:center;">0,4828</td></tr><tr><td>Extra Trees + SMOTE</td><td style="text-align:center;">0,7667</td><td style="text-align:center;">0,4182</td><td style="text-align:center;">0,5333</td></tr><tr><td><strong><code>ishaq2021improving</code> (y văn)</strong></td><td style="text-align:center;">0,9260</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Kết quả không đạt mốc y văn — và đó là điểm học quan trọng</p><p>Cấu hình SMOTE + Extra Trees ở đây <strong>không tái lập được</strong> mốc 92,6% — thấp hơn cả baseline Bước 2. Nguyên nhân nhiều khả năng: y văn dùng 100×10-fold cross-validation (ổn định hơn nhiều) trong khi notebook này chỉ dùng 1 lần Train/Test split cố định trên cỡ mẫu rất nhỏ (Test = 60 bệnh nhân). Đây là minh chứng thực tế cho rủi ro so sánh trực tiếp 1-split với kết quả CV nhiều lần — không phải lỗi cần &quot;sửa&quot; để khớp số liệu công bố.</p></div><p>👉 <a href="/hmyt-book/labs_chuyen_de/ch02_suy_tim_risk_dxai/3_improvement.ipynb">Tải <code>3_improvement.ipynb</code></a>   <a href="https://colab.research.google.com/github/fossbk-spec/hmyt-book/blob/gh-pages/labs_chuyen_de/ch02_suy_tim_risk_dxai/3_improvement.ipynb" target="_blank" rel="noreferrer"><img src="https://colab.research.google.com/assets/colab-badge.svg" alt="Colab"></a><a href="https://www.kaggle.com/kernels/welcome?src=https://raw.githubusercontent.com/fossbk-spec/hmyt-book/gh-pages/labs_chuyen_de/ch02_suy_tim_risk_dxai/3_improvement.ipynb" target="_blank" rel="noreferrer"><img src="https://kaggle.com/static/images/open-in-kaggle.svg" alt="Kaggle"></a></p><h2 id="buoc-4-—-kha-nang-giai-thich-xai-voi-shap" tabindex="-1">Bước 4 — Khả năng giải thích (XAI) với SHAP <a class="header-anchor" href="#buoc-4-—-kha-nang-giai-thich-xai-voi-shap" aria-label="Permalink to &quot;Bước 4 — Khả năng giải thích (XAI) với SHAP&quot;">​</a></h2><p><img src="'+r+'" alt="SHAP summary plot"></p><p>Xếp hạng |SHAP| trung bình (Top 5/13): <code>time</code> (1) → <code>ejection_fraction</code> (2) → <code>serum_creatinine</code> (3) → <code>age</code> (4) → <code>serum_sodium</code> (5).</p><p><code>ejection_fraction</code> và <code>serum_creatinine</code> — 2 chỉ số y văn khẳng định là quyết định nhất — <strong>đều nằm trong Top 5</strong>. Đặc trưng SHAP cao nhất (<code>time</code>) phản ánh thời gian theo dõi lâm sàng, cần diễn giải thận trọng (không phải chỉ số sinh lý trực tiếp).</p><p>👉 <a href="/hmyt-book/labs_chuyen_de/ch02_suy_tim_risk_dxai/4_xai.ipynb">Tải <code>4_xai.ipynb</code></a>   <a href="https://colab.research.google.com/github/fossbk-spec/hmyt-book/blob/gh-pages/labs_chuyen_de/ch02_suy_tim_risk_dxai/4_xai.ipynb" target="_blank" rel="noreferrer"><img src="https://colab.research.google.com/assets/colab-badge.svg" alt="Colab"></a><a href="https://www.kaggle.com/kernels/welcome?src=https://raw.githubusercontent.com/fossbk-spec/hmyt-book/gh-pages/labs_chuyen_de/ch02_suy_tim_risk_dxai/4_xai.ipynb" target="_blank" rel="noreferrer"><img src="https://kaggle.com/static/images/open-in-kaggle.svg" alt="Kaggle"></a></p><h2 id="buoc-5-—-bao-cao" tabindex="-1">Bước 5 — Báo cáo <a class="header-anchor" href="#buoc-5-—-bao-cao" aria-label="Permalink to &quot;Bước 5 — Báo cáo&quot;">​</a></h2><p>Khung báo cáo mẫu đã điền số liệu thật (không phải dữ liệu giả định) có sẵn trong repo nguồn tại <code>labs_chuyen_de/ch02_suy_tim_risk_dxai/report/5_report_outline.md</code>.</p><hr><p><em>Mã nguồn đầy đủ + dữ liệu + môi trường <code>requirements.txt</code>:</em><code>labs_chuyen_de/ch02_suy_tim_risk_dxai/</code> <em>trong repo <code>fossbk-spec/HMYT</code>.</em></p>',32)])])}const m=e(s,[["render",i]]);export{_ as __pageData,m as default};
